"""Shared named links update live fields and later students without clipboard reads on search."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import os
root=Path(__file__).resolve().parents[1]
with sync_playwright() as p:
 b=p.webkit.launch(executable_path=os.environ['PLAYWRIGHT_WEBKIT_EXECUTABLE']) if os.getenv('GIF_TEST_BROWSER')=='webkit' else p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 page=b.new_page();page.route('https://links.test/**',lambda r:r.fulfill(body='<html><body></body></html>',content_type='text/html'));page.goto('https://links.test/');page.add_script_tag(content=(root/'video-link-tools.js').read_text());page.evaluate('''()=>{window.reads=0;Object.defineProperty(navigator,'clipboard',{value:{readText:async()=>{reads++;return 'https://youtu.be/PasteTEST12'}}});window.values=[];window.addField=(name)=>{const input=document.createElement('input'),search=document.createElement('a'),paste=document.createElement('button');search.textContent='Buscar vídeo';search.href='https://www.youtube.com/results?search_query='+encodeURIComponent(name);search.onclick=e=>e.preventDefault();paste.textContent='Colar';document.body.append(input,search,paste);input.addEventListener('input',()=>values.push(input.value));WorkoutVideoLinks.attach({input,search,paste,context:()=>name});return input;};addField('Agachamento Com Barra');addField('Agachamento com barra');addField('Agachamento Taça Curtinho');}''')
 fields=page.locator('input');fields.nth(0).fill('https://youtube.com/shorts/SharedTEST12');assert fields.nth(1).input_value()=='https://youtube.com/shorts/SharedTEST12';assert fields.nth(2).input_value()=='';page.locator('a').first.click();page.evaluate("window.dispatchEvent(new Event('focus'));document.dispatchEvent(new Event('visibilitychange'))");assert page.evaluate('reads')==0
 page.evaluate("document.body.replaceChildren();addField('Agachamento COM Barra')");assert page.locator('input').input_value()=='https://youtube.com/shorts/SharedTEST12';page.locator('button').click();page.wait_for_function('reads===1');assert page.locator('input').input_value()=='https://youtu.be/PasteTEST12'
 page.reload();page.add_script_tag(content=(root/'video-link-tools.js').read_text());result=page.evaluate("JSON.parse(localStorage.getItem('treinoYouTubeLinksV1'))['agachamento com barra']");assert result=='https://youtu.be/PasteTEST12';b.close();print('PASS: matching names propagate; different variations stay separate; later fields and reload remember; search/focus never read clipboard; explicit paste works')
